import { Component, OnInit, ViewEncapsulation } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { User } from 'src/app/Modele/User.model';
import { AuthService } from 'src/app/services/auth.service';

@Component({
  selector: 'app-signup',
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.css'],
  encapsulation: ViewEncapsulation.None,
})
export class SignupComponent implements OnInit{


registerForm: FormGroup;
  nameInput: FormControl;
  emailInput: FormControl;
  passwordInput: FormControl;

  constructor(
    private router: Router,
    private authService: AuthService
  ) {
    this.nameInput = new FormControl('', [Validators.required]);
    this.emailInput = new FormControl('', [Validators.required, Validators.email]);
    this.passwordInput = new FormControl('', [Validators.required]);
    this.registerForm = new FormGroup({
      name: this.nameInput,
      email: this.emailInput,
      password: this.passwordInput,
    });
  }

  ngOnInit(): void {
  }

  signup() {
    this.authService.register(this.registerForm.value.name, this.registerForm.value.email, this.registerForm.value.password).subscribe({
      next: (user: User) => {
        alert('Register successful');
        console.log(user);


        this.router.navigate(['/login']);
      },
      error: (error) => {
        alert('Register failed');
        console.log(error);
      }
    });
  }


}
<div class="signup">



<div class="sin">
    <div class="cat">
   <img src="../../../assets/finimg.jpg" width="300px" height="250px">
    </div>

    <h1>Sign Up</h1>

    <form (ngSubmit)="signup()" [formGroup]="registerForm">
      <div>
        <label>Name:</label>
        <input type="text" placeholder="Name..." formControlName="name" />
      </div>

      <div>
        <label>Email:</label>
        <input type="email" placeholder="Email..." formControlName="email" />
     </div>

     <div>
       <label>Password:</label>
       <input
        type="password" placeholder="Password..." formControlName="password" />
    </div> 

    <div>
      <button type="submit" [disabled]="registerForm.invalid">Sign Up</button>

      <p>Already have an account? <a [routerLink]="['/login']">Login</a></p>
   </div>

    </form>
</div>
